/**
 * Client-side reference genome data.
 *
 * Bundles UCSC hg19/hg38 chromosome sizes, cytobands, and gene coordinates
 * (NCBI RefSeq Curated; each gene spans all of its transcripts) as static JSON.
 * The JSON files are generated by scripts/build_reference.py, which can also
 * check that they still match UCSC. Cumulative offsets are computed once at load time.
 */

import type { Build, Cytoband, ReferenceData } from "../types";
import { CANONICAL_CHROMOSOMES } from "../types";
import hg19Json from "./hg19.json";
import hg38Json from "./hg38.json";

interface RawBuild {
  chromosome_sizes: Record<string, number>;
  cytobands: Cytoband[];
  genes: Array<{ gene: string; chromosome: string; start: number; end: number }>;
}

function computeOffsets(sizes: Record<string, number>): Record<string, number> {
  const offsets: Record<string, number> = {};
  let running = 0;
  for (const chrom of CANONICAL_CHROMOSOMES) {
    if (chrom in sizes) {
      offsets[chrom] = running;
      running += sizes[chrom];
    }
  }
  return offsets;
}

function buildReference(raw: RawBuild): ReferenceData {
  return {
    chromosome_sizes: raw.chromosome_sizes,
    cumulative_offsets: computeOffsets(raw.chromosome_sizes),
    cytobands: raw.cytobands,
  };
}

// Pre-computed at import time — no runtime I/O.
export const hg19Reference = buildReference(hg19Json as unknown as RawBuild);
export const hg38Reference = buildReference(hg38Json as unknown as RawBuild);

export const hg19Genes = (hg19Json as unknown as RawBuild).genes;
export const hg38Genes = (hg38Json as unknown as RawBuild).genes;

export function getReference(build: Build): ReferenceData {
  return build === "hg19" ? hg19Reference : hg38Reference;
}

export function getGenes(
  build: Build
): Array<{ gene: string; chromosome: string; start: number; end: number }> {
  return build === "hg19" ? hg19Genes : hg38Genes;
}
